import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Initialize font at module level to guarantee availability
const { fontFamily: interFamily } = loadInter();



export type AutomaticBehaviorPhoneProps = Record<string, any>;

const AutomaticBehaviorPhone: React.FC<AutomaticBehaviorPhoneProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 4,
  mainText = "No Friction = Automatic Behavior.",
  phoneColor = "#111827",
  accentColor = "#3B82F6",
  feedItemColor = "#F3F4F6",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Core background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation cycle math
  const cycleFrames = Math.floor(durationInSeconds * fps);
  const t = frame % cycleFrames;

  // Phase markers (normalized frame indices for a single loop)
  const phase2 = cycleFrames * 0.25; // Pick up starts
  const phase3 = cycleFrames * 0.45; // Scroll starts
  const phase4 = cycleFrames * 0.8;  // Put down starts

  // === STEP ACTIVE STATES ===
  // Calculate seamless active states for the 3 text steps
  let step1Prog = 0;
  if (t < phase2) {
    step1Prog = interpolate(t, [0, 5, phase2 - 5, phase2], [1, 1, 1, 0], {
      extrapolateRight: "clamp",
    });
  } else if (t > cycleFrames - 10) {
    // Fade in at the very end to perfectly match frame 0
    step1Prog = interpolate(t, [cycleFrames - 10, cycleFrames], [0, 1], {
      extrapolateRight: "clamp",
    });
  }

  const step2Prog = interpolate(
    t,
    [phase2, phase2 + 5, phase3 - 5, phase3],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const step3Prog = interpolate(
    t,
    [phase3, phase3 + 5, phase4 - 5, phase4],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // === PHONE PHYSICS ===
  const phoneY = interpolate(
    t,
    [phase2, phase2 + 15, phase4, phase4 + 15],
    [0, -100, -100, 0],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const phoneScale = interpolate(
    t,
    [phase2, phase2 + 15, phase4, phase4 + 15],
    [1, 1.05, 1.05, 1],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const phoneRotate = interpolate(
    t,
    [phase2, phase2 + 15, phase4, phase4 + 15],
    [0, -4, -4, 0],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const shadowWidth = interpolate(
    t,
    [phase2, phase2 + 15, phase4, phase4 + 15],
    [260, 180, 180, 260],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const shadowOpacity = interpolate(
    t,
    [phase2, phase2 + 15, phase4, phase4 + 15],
    [0.15, 0.05, 0.05, 0.15],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // === SCROLL LOGIC ===
  const itemHeight = 120; // 100px height + 20px gap
  const itemsToScroll = 8;
  const totalScrollDist = itemHeight * itemsToScroll;

  const totalScroll = interpolate(
    t,
    [phase3, phase4],
    [0, totalScrollDist],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  
  // This offset wraps around exactly to 0 by the end of the scroll phase, ensuring a seamless loop.
  const scrollOffset = totalScroll % itemHeight;

  // === THOUGHT BUBBLE ===
  const dot1Scale = spring({ frame: t - 2, fps, config: { damping: 12 } });
  const dot2Scale = spring({ frame: t - 6, fps, config: { damping: 12 } });
  const dot3Scale = spring({ frame: t - 10, fps, config: { damping: 12 } });
  const bubbleOpacity = interpolate(t, [phase2 - 10, phase2], [1, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Screen glow when picked up
  const screenGlowOpacity = interpolate(
    t,
    [phase2, phase2 + 10, phase4, phase4 + 10],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Helper for step rendering
  const renderStep = (text: string, prog: number) => {
    return (
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 16,
          opacity: 0.3 + prog * 0.7,
          transform: `translateX(${prog * 15}px)`,
          color: phoneColor,
          fontSize: 32,
          fontWeight: 600,
          transition: "none",
        }}
      >
        <div
          style={{
            width: 12,
            height: 12,
            borderRadius: 6,
            backgroundColor: accentColor,
            opacity: prog,
            transition: "none",
          }}
        />
        {text}
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "row",
        color: phoneColor,
        transition: "none",
      }}
    >
      {/* LEFT COLUMN: Typography & Steps */}
      <div
        style={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: "10%",
          paddingRight: "5%",
          transition: "none",
        }}
      >
        <h1
          style={{
            fontSize: 72,
            fontWeight: 800,
            lineHeight: 1.1,
            margin: 0,
            maxWidth: 700,
            transition: "none",
          }}
        >
          {mainText.split("=").map((part, i) => (
            <span
              key={i}
              style={{
                display: "block",
                color: i === 1 ? accentColor : phoneColor,
                transition: "none",
              }}
            >
              {i === 1 ? `= ${part.trim()}` : part.trim()}
            </span>
          ))}
        </h1>

        <div
          style={{
            marginTop: 80,
            display: "flex",
            flexDirection: "column",
            gap: 24,
            transition: "none",
          }}
        >
          {renderStep("1. Think about phone", step1Prog)}
          {renderStep("2. Pick up", step2Prog)}
          {renderStep("3. Scroll endlessly", step3Prog)}
        </div>
      </div>

      {/* RIGHT COLUMN: The Device Animation */}
      <div
        style={{
          flex: 1,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          position: "relative",
          transition: "none",
        }}
      >
        {/* Device Container */}
        <div
          style={{
            position: "relative",
            transform: `translateY(${phoneY}px) scale(${phoneScale}) rotate(${phoneRotate}deg)`,
            transition: "none",
          }}
        >
          {/* Thought Bubble */}
          <div
            style={{
              position: "absolute",
              top: -100,
              right: -30,
              opacity: bubbleOpacity,
              transition: "none",
              zIndex: 10,
            }}
          >
            <div
              style={{
                width: 14,
                height: 14,
                borderRadius: 7,
                backgroundColor: accentColor,
                position: "absolute",
                bottom: 0,
                left: 0,
                transform: `scale(${dot1Scale})`,
                transition: "none",
              }}
            />
            <div
              style={{
                width: 24,
                height: 24,
                borderRadius: 12,
                backgroundColor: accentColor,
                position: "absolute",
                bottom: 24,
                left: 20,
                transform: `scale(${dot2Scale})`,
                transition: "none",
              }}
            />
            <div
              style={{
                width: 80,
                height: 56,
                borderRadius: 28,
                backgroundColor: accentColor,
                position: "absolute",
                bottom: 56,
                left: 44,
                transform: `scale(${dot3Scale})`,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                gap: 6,
                transition: "none",
              }}
            >
              <div style={{ width: 6, height: 6, borderRadius: 3, backgroundColor: "#FFF" }} />
              <div style={{ width: 6, height: 6, borderRadius: 3, backgroundColor: "#FFF" }} />
              <div style={{ width: 6, height: 6, borderRadius: 3, backgroundColor: "#FFF" }} />
            </div>
          </div>

          {/* Hardware Frame */}
          <div
            style={{
              width: 320,
              height: 660,
              backgroundColor: phoneColor,
              borderRadius: 50,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              boxShadow: "0 24px 48px rgba(0,0,0,0.15)",
              border: `4px solid ${phoneColor}`,
              position: "relative",
              transition: "none",
            }}
          >
            {/* Screen Inner */}
            <div
              style={{
                width: 290,
                height: 630,
                backgroundColor: "#FFFFFF",
                borderRadius: 36,
                overflow: "hidden",
                position: "relative",
                transition: "none",
              }}
            >
              {/* Screen Glow Effect */}
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  boxShadow: `inset 0 0 40px ${accentColor}`,
                  opacity: screenGlowOpacity * 0.15,
                  zIndex: 2,
                  pointerEvents: "none",
                  transition: "none",
                }}
              />

              {/* Endless Scroll Feed */}
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  transition: "none",
                }}
              >
                {/* Render enough items to cover the screen and provide a seamless wrap */}
                {Array.from({ length: 7 }).map((_, i) => {
                  const basePos = (i - 1) * itemHeight;
                  const currentY = basePos - scrollOffset;

                  return (
                    <div
                      key={i}
                      style={{
                        position: "absolute",
                        top: 0,
                        left: 16,
                        right: 16,
                        height: 100,
                        backgroundColor: feedItemColor,
                        borderRadius: 20,
                        transform: `translateY(${currentY}px)`,
                        display: "flex",
                        alignItems: "center",
                        padding: "0 20px",
                        gap: 16,
                        transition: "none",
                      }}
                    >
                      {/* Avatar skeleton */}
                      <div
                        style={{
                          width: 48,
                          height: 48,
                          borderRadius: 24,
                          backgroundColor: accentColor,
                          opacity: 0.8,
                          transition: "none",
                        }}
                      />
                      {/* Text line skeletons */}
                      <div style={{ flex: 1, transition: "none" }}>
                        <div
                          style={{
                            width: "70%",
                            height: 12,
                            backgroundColor: phoneColor,
                            opacity: 0.15,
                            borderRadius: 6,
                            marginBottom: 10,
                            transition: "none",
                          }}
                        />
                        <div
                          style={{
                            width: "40%",
                            height: 12,
                            backgroundColor: phoneColor,
                            opacity: 0.1,
                            borderRadius: 6,
                            transition: "none",
                          }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>

        {/* Shadow on table/surface */}
        <div
          style={{
            position: "absolute",
            bottom: height * 0.5 - 340, // Match visual base of resting phone
            left: "50%",
            transform: "translateX(-50%)",
            width: shadowWidth,
            height: 24,
            backgroundColor: "#000000",
            borderRadius: "50%",
            opacity: shadowOpacity,
            filter: "blur(12px)",
            transition: "none",
            pointerEvents: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default AutomaticBehaviorPhone;